(function (window, document) {
    'use strict';

    window.MateryEffects.define('ribbon', function (options) {
        var canvas = document.createElement('canvas');
        var context = canvas.getContext('2d');
        var ratio = window.devicePixelRatio || 1;
        var width = 0;
        var height = 0;
        var size = Number(options.size) || 90;
        var alpha = Number(options.alpha) || 0.6;
        var zIndex = options.zIndex == null ? -1 : options.zIndex;
        var clickChange = options.clickChange !== false;
        var phase = 0;
        var listening = false;

        canvas.className = 'ribbon-static-effect';
        canvas.style.cssText = 'opacity:' + alpha + ';position:fixed;top:0;left:0;z-index:' + zIndex + ';width:100%;height:100%;pointer-events:none';

        function resize() {
            width = window.innerWidth;
            height = window.innerHeight;
            canvas.width = width * ratio;
            canvas.height = height * ratio;
            context.setTransform(ratio, 0, 0, ratio, 0, 0);
            context.globalAlpha = alpha;
            draw();
        }

        function nextY(previousY) {
            if (height <= 0) return 0;
            for (var i = 0; i < 100; i++) {
                var candidate = previousY + (2 * Math.random() - 1.1) * size;
                if (candidate >= 0 && candidate <= height) return candidate;
            }
            return Math.max(0, Math.min(previousY, height));
        }

        function drawSection(first, second) {
            context.beginPath();
            context.moveTo(first.x, first.y);
            context.lineTo(second.x, second.y);
            var x = second.x + (2 * Math.random() - 0.25) * size;
            var y = nextY(second.y);
            context.lineTo(x, y);
            context.closePath();
            phase -= Math.PI * 2 / -50;
            var color = 127 * Math.cos(phase) + 128 << 16 |
                127 * Math.cos(phase + Math.PI * 2 / 3) + 128 << 8 |
                127 * Math.cos(phase + Math.PI * 4 / 3) + 128;
            context.fillStyle = '#' + color.toString(16);
            context.fill();
            return {x: x, y: y};
        }

        function draw() {
            context.clearRect(0, 0, width, height);
            var points = [
                {x: 0, y: 0.7 * height + size},
                {x: 0, y: 0.7 * height - size}
            ];
            while (points[1].x < width + size) {
                var next = drawSection(points[0], points[1]);
                points[0] = points[1];
                points[1] = next;
            }
        }

        function addListeners() {
            if (listening) return;
            listening = true;
            window.addEventListener('resize', resize);
            if (clickChange) document.addEventListener('click', draw);
        }

        function start() {
            if (!canvas.parentNode) document.body.appendChild(canvas);
            addListeners();
            resize();
        }

        function destroy() {
            if (listening) {
                window.removeEventListener('resize', resize);
                if (clickChange) document.removeEventListener('click', draw);
                listening = false;
            }
            if (canvas.parentNode) canvas.parentNode.removeChild(canvas);
        }

        return {
            start: start,
            pause: function () {},
            resume: function () {},
            destroy: destroy
        };
    });
})(window, document);
